function isEligible(user: User) {
  if (user.points * 0.1 - user.penalty > 100 && user.points * 0.1 - user.penalty > 0) {
    return "gold";
  }
  return "standard";
}

function charge(item: Item, taxRate: number) {
  if (item.price * (1 - item.discount) * (1 + taxRate) > 1000) {
    applyPremiumHandling();
  }
  sendToBilling(item.price * (1 - item.discount) * (1 + taxRate));
}

function totalInvoice(items: Item[], taxRate: number) {
  // Version A
  const totalA = items.reduce((sum, it) => sum + it.price * (1 - it.discount) * (1 + taxRate), 0);

  // Version B
  const totalB = items.reduce((sum, it) => {
    const netPrice = it.price * (1 - it.discount);
    return sum + netPrice * (1 + taxRate);
  }, 0);

  return { totalA, totalB };
}
